-- Lint.lua - analisis estatico leve sobre los scripts del place, 100% Luau puro.\n-- No usa servicios externos ni HTTP: el plugin corre dentro de Studio y ya tiene\n-- acceso a todo el arbol. Busca errores tipicos que Studio no siempre marca:\n-- 1) parse de sintaxis (loadstring / luau.parse si existe)\n-- 2) globals no definidos (typo detector sobre builtins y servicios conocidos)\n-- 3) math.floor(a / b) -> avisar de // en Luau\n-- 4) wait() deprecado -> task.wait\n--\n-- Devuelve una lista de hallazgos { path, line, severity, code, message, fix }.\n-- El fix es texto corto y accionable: es lo que el agente pega al Issue.\n\nlocal Lint = {}\n\nlocal SEVERITY = { ERROR = \"error\", WARN = \"warn\", INFO = \"info\" }\nLint.SEVERITY = SEVERITY\n\nlocal BUILTINS = {\n\t-- core lua\n\tassert = true, error = true, getmetatable = true, ipairs = true, next = true,\n\tpairs = true, pcall = true, print = true, rawequal = true, rawget = true,\n\trawlen = true, rawset = true, require = true, select = true, setmetatable = true,\n\ttonumber = true, tostring = true, type = true, typeof = true, unpack = true,\n\txpcall = true, warn = true,\n\t-- libs\n\tmath = true, string = true, table = true, os = true, coroutine = true,\n\tbit32 = true, utf8 = true, debug = true, buffer = true, vector = true,\n\ttask = true,\n\t-- roblox\n\tgame = true, workspace = true, script = true, plugin = true,\n\tInstance = true, Enum = true, Vector2 = true, Vector3 = true, Vector2int16 = true,\n\tVector3int16 = true, CFrame = true, Color3 = true, BrickColor = true,\n\tUDim = true, UDim2 = true, Rect = true, Region3 = true, Region3int16 = true,\n\tTweenInfo = true, NumberRange = true, NumberSequence = true, NumberSequenceKeypoint = true,\n\tColorSequence = true, ColorSequenceKeypoint = true, PhysicalProperties = true,\n\tRandom = true, DateTime = true, Path2DControlPoint = true,\n\tFont = true, Axes = true, Faces = true, Ray = true,\n\tOverlapParams = true, RaycastParams = true, CatalogSearchParams = true,\n\tFloatCurveKey = true, RotationCurveKey = true,\n\tDrawing = true, -- entornos de ejecucion extendidos\n\tsettings = true, UserSettings = true, tick = true, time = true, wait = true,\n\tspawn = true, delay = true, elapsedTime = true,\n\t_G = true, shared = true,\n\t-- tipos comunes usados como anotacion\n\tany = true, boolean = true, number = true, string2 = true, thread = true,\n\t-- self / super en metodos\n\tself = true, super = true,\n}\n\nlocal KNOWN_SERVICES = {\n\tWorkspace = true, Players = true, ReplicatedStorage = true,\n\tServerStorage = true, ServerScriptService = true, StarterGui = true,\n\tStarterPack = true, StarterPlayer = true, Lighting = true,\n\tHttpService = true, RunService = true, TweenService = true,\n\tUserInputService = true, ContextActionService = true, TeleportService = true,\n\tDataStoreService = true, MemoryStoreService = true, MessagingService = true,\n\tBadgeService = true, MarketplaceService = true, InsertService = true,\n\tCollectionService = true, PhysicsService = true, SoundService = true,\n\tChat = true, TextChatService = true, LocalizationService = true,\n\tPolicyService = true, AvatarEditorService = true, ProximityPromptService = true,\n\tPathfindingService = true, ContentProvider = true, GuiService = true,\n\tVirtualInputManager = true, HapticService = true, VRService = true,\n\tDebris = true, LogService = true, TestService = true,\n\tTeams = true, SocialService = true, GroupService = true,\n\tFriendService = true, AssetService = true, StudioService = true,\n\tScriptContext = true, Stats = true, VoiceChatService = true,\n}\n\nlocal IDENT = \"[A-Za-z_][A-Za-z0-9_]*\"\n\nlocal function lineOf(src, pos)\n\tlocal _, n = src:sub(1, pos):gsub(\"\\n\", \"\")\n\treturn n + 1\nend\n\nlocal function addFinding(out, path, line, severity, code, message, fix)\n\ttable.insert(out, {\n\t\tpath = path,\n\t\tline = line,\n\t\tseverity = severity,\n\t\tcode = code,\n\t\tmessage = message,\n\t\tfix = fix,\n\t})\nend\n\n-- Quita comentarios y cadenas para no falsear globales dentro de texto.\nlocal function stripNoise(src)\n\t-- cadenas largas [[...]]\n\tsrc = src:gsub(\"%[%[.-%]%]\", \" \")\n\t-- cadenas normales\n\tsrc = src:gsub('\"([^\"\\\\]|\\\\.)*\"', '\"\"')\n\tsrc = src:gsub(\"'([^'\\\\]|\\\\.)*'\", \"'\")\n\t-- comentarios largos ya cubiertos por %[%[...%]%]; ahora comentario de linea\n\tsrc = src:gsub(\"\\-\\-[^\\n]*\", \"\")\n\treturn src\nend\n\nlocal function lintSource(path, src)\n\tlocal findings = {}\n\n\t-- 1) sintaxis\n\tlocal ok, err\n\tif type(loadstring) == \"function\" then\n\t\tok, err = loadstring(src, \"@\" .. path)\n\tend\n\tif not ok and err then\n\t\tlocal line = tonumber(tostring(err):match(\":(%d+):\")) or 1\n\t\taddFinding(findings, path, line, SEVERITY.ERROR, \"SYNTAX\",\n\t\t\ttostring(err),\n\t\t\t\"Revisa la linea indicada: el parseador de Luau no pudo compilar el script.\")\n\t\treturn findings -- sin sintaxis no tiene sentido seguir\n\tend\n\n\tlocal clean = stripNoise(src)\n\n\t-- 2) globals\n\tfor ident in clean:gmatch(IDENT) do\n\t\tif not BUILTINS[ident] and not KNOWN_SERVICES[ident] then\n\t\t\t-- solo interesan los que se usan como valor (palabra seguida de no-palabra)\n\t\t\t-- esto ya es lo que da gmatch; filtramos palabras clave\n\t\t\tlocal keywords = {\n\t\t\t\t[\"local\"] = true, [\"function\"] = true, [\"end\"] = true, [\"if\"] = true,\n\t\t\t\t[\"then\"] = true, [\"else\"] = true, [\"elseif\"] = true, [\"for\"] = true,\n\t\t\t\t[\"while\"] = true, [\"do\"] = true, [\"repeat\"] = true, [\"until\"] = true,\n\t\t\t\t[\"return\"] = true, [\"break\"] = true, [\"continue\"] = true, [\"in\"] = true,\n\t\t\t\t[\"and\"] = true, [\"or\"] = true, [\"not\"] = true, [\"true\"] = true,\n\t\t\t\t[\"false\"] = true, [\"nil\"] = true, [\"export\"] = true, [\"type\"] = true,\n\t\t\t}\n\t\t\tif not keywords[ident] then\n\t\t\t\t-- evitamos duplicados masivos: una entrada por (ident, linea de primera aparicion)\n\t\t\t\tlocal firstPos = clean:find(\"%f[%w]\" .. ident .. \"%f[%W]\")\n\t\t\t\tlocal line = firstPos and lineOf(clean, firstPos) or 1\n\t\t\t\t-- solo reportar si parece un acceso a global (no va precedido de . o :)\n\t\t\t\tlocal preceded = firstPos and clean:sub(math.max(1, firstPos - 1), math.max(1, firstPos - 1))\n\t\t\t\tif preceded ~= \".\" and preceded ~= \":\" then\n\t\t\t\t\tlocal already = false\n\t\t\t\t\tfor _, f in ipairs(findings) do\n\t\t\t\t\t\tif f.code == \"UNDEFINED_GLOBAL\" and f.message:find(ident, 1, true) then\n\t\t\t\t\t\t\talready = true\n\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\t\tif not already then\n\t\t\t\t\t\taddFinding(findings, path, line, SEVERITY.WARN, \"UNDEFINED_GLOBAL\",\n\t\t\t\t\t\t(\"Global '%s' no esta en builtins ni en servicios conocidos\"):format(ident),\n\t\t\t\t\t\t(\"Si es un servicio, usa game:GetService(\\\"%s\\\"); si es una variable, declarala con 'local' antes de usarla.\"):format(ident))\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\t-- 3) math.floor(a / b)\n\tfor pos in clean:gmatch(\"()math%.floor%s*%([^%)]*/[^%)]*%)\") do\n\t\taddFinding(findings, path, lineOf(clean, pos), SEVERITY.INFO, \"FLOOR_DIV\",\n\t\t\t\"math.floor(a / b) es division de suelo doble\",\n\t\t\t\"En Luau puedes escribir a // b, que es mas claro y rapido.\")\n\tend\n\n\t-- 4) wait() / spawn() deprecados\n\tfor pos in clean:gmatch(\"()%f[%w]wait%s*%(\") do\n\t\taddFinding(findings, path, lineOf(clean, pos), SEVERITY.INFO, \"DEPRECATED_WAIT\",\n\t\t\t\"wait() esta deprecado\",\n\t\t\t\"Usa task.wait() para el mismo comportamiento con mejor rendimiento.\")\n\tend\n\tfor pos in clean:gmatch(\"()%f[%w]spawn%s*%(\") do\n\t\taddFinding(findings, path, lineOf(clean, pos), SEVERITY.INFO, \"DEPRECATED_SPAWN\",\n\t\t\t\"spawn() esta deprecado\",\n\t\t\t\"Usa task.spawn() o task.defer().\")\n\tend\n\n\treturn findings\nend\n\n-- Lint.Place(root) -> findings[]. Recorre todo el DataModel por debajo de `root`\n-- (o game si root es nil). Omite el propio plugin y el RuntimeStaging.\nfunction Lint.Place(root)\n\troot = root or game\n\tlocal out = {}\n\tlocal function walk(node)\n\t\tlocal name = node.Name\n\t\tif name == \"RobloxAgentBridge\" or name == \"RuntimeStaging\" or name == \"_RBX_Trash\" then\n\t\t\treturn\n\t\tend\n\t\tif node:IsA(\"LuaSourceContainer\") then\n\t\t\tlocal src = node.Source\n\t\t\tif type(src) == \"string\" and #src > 0 then\n\t\t\t\tlocal ok, res = pcall(lintSource, node:GetFullName(), src)\n\t\t\t\tif ok and res then\n\t\t\t\t\tfor _, f in ipairs(res) do\n\t\t\t\t\t\ttable.insert(out, f)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tfor _, child in ipairs(node:GetChildren()) do\n\t\t\twalk(child)\n\t\tend\n\tend\n\twalk(root)\n\treturn out\nend\n\nreturn Lint\n